/**
 * Verified Strait of Canso transmission crossings, restored overhead power lines and communication masts
 * for the Point Tupper, Canso Causeway and West Bay areas (grok-bots#1152 / #1328).
 *
 * Sources:
 * - Transmission tower positions and routes: © OpenStreetMap contributors (ODbL); way/node IDs retained below.
 * - Restored non-OSM overhead lines and unmatched masts: Province of Nova Scotia NSTDB UTTR50/UTTO60 (OGL-NS).
 * - Communication mast heights (where OSM omits height): NRCan CanVec ManMade (OGL-Canada).
 * - Auld's Cove crossing tower heights (158 m lattice / 164 m overall; 26 m anchors) and vertically aligned
 *   flashing white crossing lights: Nova Scotia Environmental Assessment public records (Auld's Cove 2016
 *   registration Table 2.2 & p. 51, and 2025 Strait crossing assessment Appendix A p. 49).
 * - Communication mast red night light classes (A0 <=45 m, A1 >45-105 m, A2 >105-210 m): Transport Canada Standard 621.
 *
 * Every support's drawn base is verified clear of baked roads and building footprints across all overlapping areas.
 * Where an OSM support's drawn base reached a road, it moved up to 60 m along its own line, or was dropped when the
 * joined span still clears the ground by 6 m (two supports). One L6518 support (n2760179224) stays; see tall-check. Ground elevations and span profiles are sampled from the baked NRCan DTM tiles (EPSG:2961).
 */

/** Compact power tower tuple: [e, n, ground, height, kind (0=standard, 1=double, 2=crossing), light (0=none, 4=white strobe), osmNodeId]. */
export type CompactPowerTower = readonly [number, number, number, number, 0 | 1 | 2, 0 | 4, number];
/** Compact span tuple: [sag, ...groundSamples]. */
export type CompactSpan = readonly [number, ...number[]];
export interface CompactPowerLine {
  readonly src: string;
  readonly ref: string;
  readonly c: 1 | 2;
  readonly t: readonly CompactPowerTower[];
  readonly s: readonly CompactSpan[];
  /** Only for this area's mid box: a restored legacy piece belongs to the area it was baked for. */
  readonly m?: readonly [number, number, number, number];
}
/** Compact communication mast tuple: [e, n, ground, height, light (1=A0, 2=A1, 3=A2), source]. */
export type CompactMast = readonly [number, number, number, number, 1 | 2 | 3, string];

